const sharp = require("sharp");
const fs = require("fs");
const path = require("path");

// We generate local public URLs by default so the UI works immediately.
// Once you upload the generated files to Zata, you can prepend:
//   https://idr01.zata.ai/devstoragev1/public
const LOCAL_PUBLIC_PREFIX = "/homepage/creativeStyle/indian-styles";

const SRC_ROOT = path.join(
  __dirname,
  "..",
  "public",
  "HomePage",
  "creativeStyle",
  "Indian Styles",
);

const DST_ROOT = path.join(
  __dirname,
  "..",
  "public",
  "homepage",
  "creativeStyle",
  "indian-styles",
);

const OUT_MAP_TS = path.join(
  __dirname,
  "..",
  "src",
  "styles",
  "indianStylePreviews.ts",
);

function slugify(text) {
  return String(text)
    .toLowerCase()
    .trim()
    .replace(/[\u2013\u2014]/g, "-")
    // keep letters/numbers/space/hyphen only
    .replace(/[^\w\s-]/g, "")
    .replace(/[\s\-_]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function ensureDir(dir) {
  fs.mkdirSync(dir, { recursive: true });
}

function isImageExt(ext) {
  return [".png", ".jpg", ".jpeg", ".webp"].includes(ext);
}

function detectVn(baseLower) {
  // matches: v1, V1, foo-v1, foo_V1_1, foo-V1-1, etc
  const m = baseLower.match(/(?:^|[-_ ])v([123])(?:$|[-_ ])/i);
  return m ? Number(m[1]) : null;
}

function detectStyleKey({ baseLower, relDirSegmentsSlug }) {
  // preferred: prefix before "-v1"/"_v1"
  const split = baseLower.split(/[-_ ]v[123](?:[-_ ].*)?$/i);
  const prefix = (split[0] || "").trim();
  const keyFromPrefix = slugify(prefix);
  if (keyFromPrefix && keyFromPrefix !== "v") return keyFromPrefix;

  // fallback: folder name (last segment)
  const lastSeg = relDirSegmentsSlug[relDirSegmentsSlug.length - 1] || "";
  const keyFromFolder = slugify(lastSeg);
  return keyFromFolder || null;
}

function vnFromFolderSegments(relSegmentsOriginal) {
  // supports folder layout like: .../V1/..., .../v2/...
  for (let i = relSegmentsOriginal.length - 1; i >= 0; i -= 1) {
    const seg = String(relSegmentsOriginal[i] || "").trim().toLowerCase();
    if (seg === "v1") return 1;
    if (seg === "v2") return 2;
    if (seg === "v3") return 3;
  }
  return null;
}

function styleKeyFromFolderLayout(relSegmentsOriginal) {
  // If there is a V1/V2/V3 folder, the style is the folder just before it.
  for (let i = relSegmentsOriginal.length - 1; i >= 0; i -= 1) {
    const seg = String(relSegmentsOriginal[i] || "").trim().toLowerCase();
    if (seg === "v1" || seg === "v2" || seg === "v3") {
      const parent = relSegmentsOriginal[i - 1] || "";
      return slugify(parent);
    }
  }
  return null;
}

async function walkAndConvert(dir, relSegmentsOriginal) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const srcPath = path.join(dir, entry.name);

    if (entry.isDirectory()) {
      await walkAndConvert(srcPath, [...relSegmentsOriginal, entry.name]);
      continue;
    }

    const ext = path.extname(entry.name).toLowerCase();
    if (!isImageExt(ext)) continue;

    const relSegmentsSlug = relSegmentsOriginal.map(slugify).filter(Boolean);
    const dstDir = path.join(DST_ROOT, ...relSegmentsSlug);
    ensureDir(dstDir);

    const baseName = path.basename(entry.name, ext);
    const baseLower = baseName.toLowerCase();

    const vn = detectVn(baseLower) ?? vnFromFolderSegments(relSegmentsOriginal);
    const dstBase = vn ? `v${vn}` : slugify(baseName) || "image";
    const dstFile = `${dstBase}.avif`;

    const dstPath = path.join(dstDir, dstFile);

    const relUrl = `${LOCAL_PUBLIC_PREFIX}/${[...relSegmentsSlug, dstFile].join("/")}`;

    try {
      await sharp(srcPath).avif({ quality: 70 }).toFile(dstPath);
      convertedCount += 1;
    } catch (e) {
      console.error("[convert] failed:", srcPath, e.message);
      continue;
    }

    if (vn) {
      const styleKey =
        styleKeyFromFolderLayout(relSegmentsOriginal) ||
        detectStyleKey({ baseLower, relDirSegmentsSlug: relSegmentsSlug });
      if (styleKey) {
        previewMap[styleKey] ||= {};
        previewMap[styleKey][`v${vn}`] = relUrl;
      }
    }
  }
}

function toTsFile(previews) {
  const keys = Object.keys(previews).sort();
  const body = keys
    .map((k) => {
      const v1 = previews[k]?.v1 || "";
      const v2 = previews[k]?.v2 || "";
      const v3 = previews[k]?.v3 || "";
      // Only export complete triples (avoids broken UI)
      if (!v1 || !v2 || !v3) return null;
      return `  "${k}": { v1: "${v1}", v2: "${v2}", v3: "${v3}" },`;
    })
    .filter(Boolean)
    .join("\n");

  return `// Auto-generated by scripts/convert-indian-styles-to-avif.js
export type IndianStylePreviewTriple = { v1: string; v2: string; v3: string };

export const INDIAN_STYLE_PREVIEWS: Record<string, IndianStylePreviewTriple> = {
${body}
};
`;
}

let convertedCount = 0;
const previewMap = {};

async function main() {
  if (!fs.existsSync(SRC_ROOT)) {
    console.error("[convert] source folder not found:", SRC_ROOT);
    process.exit(1);
  }

  ensureDir(DST_ROOT);
  ensureDir(path.dirname(OUT_MAP_TS));

  console.log("[convert] src:", SRC_ROOT);
  console.log("[convert] dst:", DST_ROOT);

  await walkAndConvert(SRC_ROOT, []);

  const ts = toTsFile(previewMap);
  fs.writeFileSync(OUT_MAP_TS, ts, "utf8");

  const completeTriples = Object.values(previewMap).filter(
    (x) => x && x.v1 && x.v2 && x.v3,
  ).length;

  console.log(`[convert] converted images: ${convertedCount}`);
  console.log(`[convert] preview triples found: ${completeTriples}`);
  console.log("[convert] wrote:", OUT_MAP_TS);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

